#include <Snooker/Rules/Miss.h>
#include <Snooker/Rules/BallValues.h>
#include <Snooker/Serialization/Text.h>
#include <algorithm>
#include <sstream>
namespace Snooker
{
namespace {bool Fail(std::string* e,const char* m){if(e)*e=m;return false;}bool Token(const std::string& v){return !v.empty()&&v.find_first_of(" \t\r\n")==std::string::npos;}const BallDefinition* Find(const std::vector<BallDefinition>& d,BallId id){auto i=std::find_if(d.begin(),d.end(),[&](const auto& b){return b.Id==id;});return i==d.end()?nullptr:&*i;}bool Active(const PhysicsSnapshot& s,std::size_t i){return s.PocketStates.empty()||s.PocketStates[i].State!=PocketState::Potted;}bool Blocked(const Vec3d&a,const Vec3d&b,const PhysicsSnapshot&s,const std::vector<BallDefinition>&d,BallId cue,BallId target){const auto ab=b-a;for(std::size_t i=0;i<s.Balls.size();++i){if(!Active(s,i)||s.Balls[i].Id==cue||s.Balls[i].Id==target)continue;const auto* o=Find(d,s.Balls[i].Id);const auto* c=Find(d,cue);const double t=std::clamp((s.Balls[i].PositionMeters-a).Dot(ab)/ab.LengthSquared(),0.0,1.0);if((s.Balls[i].PositionMeters-(a+ab*t)).Length()<o->RadiusMeters+c->RadiusMeters-1e-10)return true;}return false;}bool FullClear(const ShotPhysicsResult&r,EBallType on){const auto* cue=Find(r.Definitions,r.CueBall);auto ci=std::find_if(r.Initial.Balls.begin(),r.Initial.Balls.end(),[&](const auto& b){return b.Id==r.CueBall;});for(std::size_t i=0;i<r.Initial.Balls.size();++i){const auto* target=Find(r.Definitions,r.Initial.Balls[i].Id);if(!target||target->Type!=on||!Active(r.Initial,i))continue;const auto delta=r.Initial.Balls[i].PositionMeters-ci->PositionMeters;const double len=std::hypot(delta.X,delta.Y);if(len<=cue->RadiusMeters+target->RadiusMeters)continue;const Vec3d dir{delta.X/len,delta.Y/len,0},perp{-dir.Y,dir.X,0};const auto end=r.Initial.Balls[i].PositionMeters-dir*(cue->RadiusMeters+target->RadiusMeters);if(!Blocked(ci->PositionMeters,end+perp*cue->RadiusMeters,r.Initial,r.Definitions,r.CueBall,target->Id)&&!Blocked(ci->PositionMeters,end-perp*cue->RadiusMeters,r.Initial,r.Definitions,r.CueBall,target->Id))return true;}return false;}int Remaining(const MatchState&s){if(s.Phase==FramePhase::Reds)return int(s.RemainingReds)*8+27;if(s.Phase==FramePhase::ColorAfterRed)return 7+int(s.RemainingReds)*8+27;int sum=0;for(auto t=s.BallOn;;t=t==EBallType::Yellow?EBallType::Green:t==EBallType::Green?EBallType::Brown:t==EBallType::Brown?EBallType::Blue:t==EBallType::Blue?EBallType::Pink:EBallType::Black){int v=0;TryBallValue(t,v);sum+=v;if(t==EBallType::Black)break;}return sum;}}
bool RulesProfile::IsValid(std::string* Error)const{if(!Token(Id)||MinimumFoul<4||MinimumFoul>7||!IsFinite(DLineX)||!IsFinite(DRadius)||DRadius<=0)return Fail(Error,"invalid rules profile");return true;}
std::string RulesProfile::Serialize()const{std::ostringstream s;s.imbue(std::locale::classic());s<<"snooker-rules-v1 "<<Id<<' '<<int(MissEnabled)<<' '<<MinimumFoul<<' '<<DLineX<<' '<<DRadius;return s.str();}
bool RulesProfile::Deserialize(const std::string&t,RulesProfile&out,std::string*e){std::istringstream s(t);s.imbue(std::locale::classic());RulesProfile r;std::string m;unsigned miss;if(!(s>>m>>r.Id>>miss)||m!="snooker-rules-v1"||miss>1||!ReadUnsigned(s,r.MinimumFoul)||!(s>>r.DLineX>>r.DRadius))return Fail(e,"invalid rules profile schema");r.MissEnabled=miss;s>>std::ws;if(!s.eof()||!r.IsValid(e))return false;out=r;return true;}
bool MissResult::IsValid(std::string*e)const{if(!State.IsValid(e)||(Miss&&(!Foul||!CanRestore||Reason.empty()))||(!Foul&&(Miss||!Reason.empty())))return Fail(e,"invalid Miss result");return true;}
bool EvaluateMiss(const MatchState&s,const ShotPhysicsResult&i,const FirstContactResult&c,const RulesProfile&p,MissResult&out,std::string*e){if(!s.IsValid(e)||!i.IsValid(e)||!c.IsValid(e)||!p.IsValid(e))return false;MissResult r;r.State=s;r.Foul=c.IsFoul();if(r.Foul)r.Reason=c.Kind==FirstContactKind::NoContact?"no first contact":"wrong first contact";const int behind=int(s.Scores[1-s.CurrentPlayer])-int(s.Scores[s.CurrentPlayer]);r.NeedsSnookers=behind>Remaining(s);r.ClearFullBallAvailable=FullClear(i,s.BallOn);r.Miss=r.Foul&&p.MissEnabled&&r.ClearFullBallAvailable&&!r.NeedsSnookers;r.CanRestore=r.Miss;r.State.MissPending=r.Miss;if(!r.IsValid(e))return false;out=r;return true;}
bool MissResolution::IsValid(std::string*e)const{if(!State.IsValid(e)||!Physics.IsValid(e)||PlayerToPlay>1||State.CurrentPlayer!=PlayerToPlay)return Fail(e,"invalid Miss resolution");return true;}
bool ResolveMiss(const MissResult&r,MissChoice choice,const PhysicsSnapshot&before,const PhysicsSnapshot&current,MissResolution&out,std::string*e){if(!r.IsValid(e)||!r.Miss||!before.IsValid(e)||!current.IsValid(e)||before.PhysicsParameterVersion!=current.PhysicsParameterVersion)return Fail(e,"Miss resolution unavailable");MissResolution x;x.State=r.State;x.State.MissPending=false;if(choice==MissChoice::RestoreAndReplay){x.Restored=true;x.Physics=before;x.State.CurrentPlayer=r.State.CurrentPlayer;}else{x.Physics=current;x.State.CurrentPlayer=1-r.State.CurrentPlayer;}x.PlayerToPlay=x.State.CurrentPlayer;if(!x.IsValid(e))return false;out=x;return true;}
}
